L700: /** 合并已读范围，让多次分页读取能构成完整读回。 */
L701: function mergeRanges(ranges) {
L702:   const merged = [];
L703:   for (const [start, end] of ranges.sort((left, right) => left[0] - right[0])) {
L704:     const last = merged.at(-1);
L705:     if (last && start <= last[1] + 1) last[1] = Math.max(last[1], end);
L706:     else merged.push([start, end]);
L707:   }
L708:   return merged;
L709: }
