L273: /** 受控写入事务维护正文、单份改前备份和逐文件更新记录。 */
L274: export function replaceWithHistory(root, file, content, note, tag, markers) {
L275:   const before = readBytes(root, file);
L276:   const after = Buffer.from(content, "utf8");
L277:   if (equal(before, after)) return { path: file, changed: false, sha256: digest(after) };
L278:   const log = MANAGED + "/changes/" + file + ".md";
L279:   const backup = MANAGED + "/latest_backup/" + file;
L280:   const oldLog = readBytes(root, log);
L281:   const summary = note.trim().replace(/\s+/g, " ").slice(0, 500);
L282:   const record = "- " + new Date().toISOString() + " " + tag + " " + summary + " SHA-256 " + digest(after) + "\n";
L283:   const history = Buffer.from(record + (oldLog ? text(oldLog) : ""), "utf8");
L284:   if (history.length > LIMIT || after.length > LIMIT) throw new Error("内容或更新日志超过受控工具的大小上限");
L285:   const marker = keyOf(file);
L286:   if (markers[marker] !== tag) {
L287:     if (before) replaceBytes(root, backup, before, readBytes(root, backup));
L288:     if (oldLog) {
L289:       const logBackup = MANAGED + "/latest_backup/" + log;
L290:       replaceBytes(root, logBackup, oldLog, readBytes(root, logBackup));
L291:     }
L292:   }
L293:   replaceBytes(root, log, history, oldLog);
L294:   try { replaceBytes(root, file, after, before); }
L295:   catch (error) {
L296:     replaceBytes(root, log, oldLog, history);
L297:     throw error;
L298:   }
L299:   markers[marker] = tag;
L300:   return { path: file, changed: true, sha256: digest(after), log, ...(before ? { backup } : {}) };
L301: }

