L799: /** 续派前等原子会话收尾，超时保持原状态以便重试。 */
L800: async function waitIdle(agent, signal) {
L801:   const bounded = AbortSignal.any([signal, AbortSignal.timeout(20000)]);
L802:   bounded.throwIfAborted();
L803:   let abort;
L804:   try {
L805:     await Promise.race([agent.whenIdle(), new Promise((_, reject) => {
L806:       abort = () => reject(bounded.reason);
L807:       bounded.addEventListener("abort", abort, { once: true });
L808:     })]);
L809:   } finally { if (abort) bounded.removeEventListener("abort", abort); }
